INSERT INTO items (item_type_id, content, answer_set, word_count, difficulty, cefr_level, status, pool, topic, exam_part_id, exam_order) VALUES
('typing', '{"text": "Good communication is one of the most valuable skills in any workplace. Employees who communicate clearly with coworkers and supervisors tend to complete projects more efficiently and avoid unnecessary misunderstandings that can slow down important work. Written communication, such as emails and reports, requires special attention because the reader cannot ask immediate questions or hear the writer''s tone of voice directly. For this reason, it is important to organize information logically, use clear and simple language, and proofread every message carefully before sending it to colleagues or clients. Taking a few extra minutes to review a message can prevent confusion and save valuable time later. Companies that actively encourage strong communication skills among employees often see noticeable improvements in teamwork, productivity, and overall workplace satisfaction."}'::jsonb, '{"exact": "Good communication is one of the most valuable skills in any workplace. Employees who communicate clearly with coworkers and supervisors tend to complete projects more efficiently and avoid unnecessary misunderstandings that can slow down important work. Written communication, such as emails and reports, requires special attention because the reader cannot ask immediate questions or hear the writer''s tone of voice directly. For this reason, it is important to organize information logically, use clear and simple language, and proofread every message carefully before sending it to colleagues or clients. Taking a few extra minutes to review a message can prevent confusion and save valuable time later. Companies that actively encourage strong communication skills among employees often see noticeable improvements in teamwork, productivity, and overall workplace satisfaction."}'::jsonb, 125, 0.50, 'B2', 'approved', 'exam', 'business', 'c1000000-0000-4000-8000-000000000011', 1);
