INSERT INTO items (item_type_id, content, answer_set, word_count, difficulty, cefr_level, status, pool, topic, exam_part_id, exam_order) VALUES
('passage_reconstruction', '{"passage": "Diego had been waiting for a promotion for over a year. When his manager finally called him into the office, he felt nervous. To his relief, he was offered the position along with a raise. Diego left the meeting feeling proud and excited about the new role."}'::jsonb, '{"key_points": ["Diego waited over a year for a promotion", "he felt nervous in the meeting", "he was offered the position and a raise", "he felt proud and excited"]}'::jsonb, 46, 0.52, 'B1', 'approved', 'exam', 'business', 'c1000000-0000-4000-8000-000000000014', 1),
('passage_reconstruction', '{"passage": "Priya submitted her project a day before the deadline. Her supervisor reviewed it and found a small error in the calculations. Priya quickly fixed the mistake and resubmitted the file that same afternoon. Her supervisor approved it without any further issues."}'::jsonb, '{"key_points": ["Priya submitted early", "her supervisor found a small error", "she fixed it the same afternoon", "it was approved without further issues"]}'::jsonb, 41, 0.55, 'B2', 'approved', 'exam', 'business', 'c1000000-0000-4000-8000-000000000014', 2),
('passage_reconstruction', '{"passage": "Thank you for your email regarding the delayed shipment. We apologize for the inconvenience this has caused your business. Our supplier experienced an unexpected delay, but the new items should arrive within three business days. We will provide a small discount on your next order as an apology."}'::jsonb, '{"key_points": ["apologizes for the delayed shipment", "the supplier caused the delay", "items will arrive within three days", "offers a discount on the next order"]}'::jsonb, 48, 0.56, 'B2', 'approved', 'exam', 'business', 'c1000000-0000-4000-8000-000000000014', 3),
('passage_reconstruction', '{"passage": "I wanted to follow up on our meeting last week regarding the budget proposal. After reviewing the numbers again, I believe we can reduce costs by adjusting the marketing timeline. Please let me know if you would like to discuss this further before Friday''s deadline."}'::jsonb, '{"key_points": ["follows up on last week''s budget meeting", "suggests reducing costs via the marketing timeline", "asks to discuss further before Friday''s deadline"]}'::jsonb, 45, 0.58, 'B2', 'approved', 'exam', 'business', 'c1000000-0000-4000-8000-000000000014', 4);
INSERT INTO items (item_type_id, content, answer_set, difficulty, cefr_level, status, pool, topic, exam_part_id, exam_order) VALUES
('email_writing', '{"prompt": "You work at a software company. Your manager, Mr. Alvarez, wants to improve team morale but has a limited budget. Write an email to him suggesting three ways to improve morale without spending much money. Your suggestions must come from the following three themes: flexible work hours, recognition programs, team lunches. You should include all three themes and provide supporting ideas for each of your suggestions."}'::jsonb, null, 0.55, 'B2', 'approved', 'exam', 'business', 'c1000000-0000-4000-8000-000000000015', 1),
('email_writing', '{"prompt": "You work at a retail store. A regular customer, Mrs. Chen, complained that a recent online order arrived late and slightly damaged. Write an email to her apologizing for the issue and offering a solution. Your response must address the following three themes: an apology for the delay, an apology for the damage, and an offer to make it right. You should include all three themes with a clear, professional tone."}'::jsonb, null, 0.58, 'B2', 'approved', 'exam', 'business', 'c1000000-0000-4000-8000-000000000015', 2);
